package com.silverguardian.prototype.data.dao;
import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import com.silverguardian.prototype.data.ElderlyDbHelper;import com.silverguardian.prototype.models.Medicine;import java.util.*;
public class MedicineDao{
 private final ElderlyDbHelper h;public MedicineDao(ElderlyDbHelper h){this.h=h;}
 public List<Medicine> readAll(int uid,String today){List<Medicine>r=new ArrayList<>();Cursor c=h.getReadableDatabase().rawQuery("SELECT m.id,m.name,m.type,m.time,m.method,m.description,m.image,CASE WHEN t.id IS NULL THEN 0 ELSE 1 END,m.advance_minutes,m.repeat_count,m.repeat_interval FROM user_medicines m LEFT JOIN medicine_taken t ON t.medicine_id=m.id AND t.user_id=m.user_id AND t.taken_date=? WHERE m.user_id=? ORDER BY m.id",new String[]{today,String.valueOf(uid)});while(c.moveToNext())r.add(new Medicine(c.getInt(0),c.getString(1),c.getString(2),c.getString(3),c.getString(4),c.getString(5),c.getString(6),c.getInt(7)==1,c.getInt(8),c.getInt(9),c.getInt(10)));c.close();return r;}
 public int add(int uid,String name,String type,String time,String method,String desc,int advance,int repeats,int interval){ContentValues v=new ContentValues();v.put("user_id",uid);v.put("name",name);v.put("type",type);v.put("time",time);v.put("method",method);v.put("description",desc);v.put("image","");v.put("advance_minutes",advance);v.put("repeat_count",repeats);v.put("repeat_interval",interval);return(int)h.getWritableDatabase().insertOrThrow("user_medicines",null,v);}
 public void delete(int id){h.getWritableDatabase().delete("user_medicines","id=?",new String[]{String.valueOf(id)});}
 public void setTaken(int uid,int mid,boolean taken,String day){if(taken){ContentValues v=new ContentValues();v.put("user_id",uid);v.put("medicine_id",mid);v.put("taken_date",day);h.getWritableDatabase().insertWithOnConflict("medicine_taken",null,v,SQLiteDatabase.CONFLICT_IGNORE);}else h.getWritableDatabase().delete("medicine_taken","user_id=? AND medicine_id=? AND taken_date=?",new String[]{String.valueOf(uid),String.valueOf(mid),day});}
 public boolean isTakenToday(int uid,int mid,String day){Cursor c=h.getReadableDatabase().rawQuery("SELECT 1 FROM medicine_taken WHERE user_id=? AND medicine_id=? AND taken_date=?",new String[]{String.valueOf(uid),String.valueOf(mid),day});boolean x=c.moveToFirst();c.close();return x;}
}